mapper.select:
SELECT d.summary_no AS summaryNo, d.location_id AS wardId, l.name AS wardName, o.id AS deptId, o.name AS deptName, SUM(d.quantity) AS totalQty, COUNT(DISTINCT d.patient_id) AS patientCount, d.status_enum AS status, MIN(d.created_at) AS createTime, MAX(d.dispense_time) AS dispenseTime, p.name AS operatorName FROM med_medication_dispense d LEFT JOIN adm_location l ON l.id = d.location_id AND l.is_deleted = 0 LEFT JOIN adm_organization o ON o.id = l.organization_id AND o.is_deleted = 0 LEFT JOIN adm_practitioner p ON p.id = d.practitioner_id AND p.is_deleted = 0 WHERE d.is_deleted = 0
AND d.summary_no LIKE CONCAT('%', #{summaryNo}, '%')
AND d.location_id = #{wardId}
AND l.name LIKE CONCAT('%', #{wardName}, '%')
AND d.status_enum = #{status}
AND d.created_at >= #{createTimeStart}
AND d.created_at <= #{createTimeEnd}
GROUP BY d.summary_no, d.location_id, l.name, o.id, o.name, d.status_enum, p.name ORDER BY MIN(d.created_at) DESC
